//! SQLite persistence operations for the recipe catalogue.
use crate::{MealPlannerError, MealPlannerStore, Recipe, RecipeDraft};
use rusqlite::{OptionalExtension, params};
use std::time::{SystemTime, UNIX_EPOCH};
impl MealPlannerStore {
 pub fn create_recipe(&self,owner_id:&str,draft:RecipeDraft)->Result<Recipe,MealPlannerError>{let draft=draft.validate().map_err(MealPlannerError::InvalidInput)?;let payload=serde_json::to_string(&draft)?;let now=timestamp();let mut c=self.connection.lock().map_err(|_|MealPlannerError::LockPoisoned)?;let tx=c.transaction()?;tx.execute("INSERT INTO recipes(title,payload,owner_id,family_id,created_at,updated_at) VALUES (?1,?2,?3,?4,?5,?5)",params![draft.title,payload,owner_id,draft.family_id,now])?;let id=tx.last_insert_rowid();tx.commit()?;Ok(Recipe{id,owner_id:owner_id.to_owned(),family_id:draft.family_id.clone(),draft,created_at:now,updated_at:now})}
 pub fn update_recipe(&self,id:i64,owner_id:&str,draft:RecipeDraft)->Result<Recipe,MealPlannerError>{let draft=draft.validate().map_err(MealPlannerError::InvalidInput)?;let payload=serde_json::to_string(&draft)?;let now=timestamp();let c=self.connection.lock().map_err(|_|MealPlannerError::LockPoisoned)?;if c.execute("UPDATE recipes SET title=?1,payload=?2,family_id=?3,updated_at=?4 WHERE id=?5 AND owner_id=?6",params![draft.title,payload,draft.family_id,now,id,owner_id])?==0{return Err(MealPlannerError::NotFound)}load_recipe(&c,id)?.ok_or(MealPlannerError::NotFound)}
 pub fn get_recipe(&self,id:i64,owner_id:&str,families:&[String])->Result<Recipe,MealPlannerError>{let c=self.connection.lock().map_err(|_|MealPlannerError::LockPoisoned)?;let r=load_recipe(&c,id)?.ok_or(MealPlannerError::NotFound)?;if r.owner_id!=owner_id&&!r.family_id.as_ref().is_some_and(|f|families.iter().any(|x|x==f)){return Err(MealPlannerError::NotFound)}Ok(r)}
 pub fn list_recipes(&self,owner_id:&str,families:&[String],query:Option<&str>)->Result<Vec<Recipe>,MealPlannerError>{let c=self.connection.lock().map_err(|_|MealPlannerError::LockPoisoned)?;let mut s=c.prepare("SELECT id,payload,owner_id,family_id,created_at,updated_at FROM recipes ORDER BY lower(title),id")?;let rows=s.query_map([],row_recipe)?.collect::<Result<Vec<_>,_>>()?;let needle=query.map(str::trim).filter(|v|!v.is_empty()).map(str::to_lowercase);Ok(rows.into_iter().filter(|r|(r.owner_id==owner_id||r.family_id.as_ref().is_some_and(|f|families.iter().any(|x|x==f)))&&needle.as_ref().is_none_or(|n|{let d=&r.draft;d.title.to_lowercase().contains(n)||d.description.as_deref().is_some_and(|v|v.to_lowercase().contains(n))||d.ingredients.iter().any(|i|i.name.to_lowercase().contains(n))||d.tags.iter().chain(&d.categories).any(|v|v.to_lowercase().contains(n))})).collect())}
 pub fn delete_recipe(&self,id:i64,owner_id:&str)->Result<(),MealPlannerError>{let c=self.connection.lock().map_err(|_|MealPlannerError::LockPoisoned)?;if c.execute("DELETE FROM recipes WHERE id=?1 AND owner_id=?2",params![id,owner_id])?==0{return Err(MealPlannerError::NotFound)}Ok(())}
}
fn row_recipe(row:&rusqlite::Row<'_>)->rusqlite::Result<Recipe>{let payload:String=row.get(1)?;let draft=serde_json::from_str(&payload).map_err(|e|rusqlite::Error::FromSqlConversionFailure(1,rusqlite::types::Type::Text,Box::new(e)))?;Ok(Recipe{id:row.get(0)?,draft,owner_id:row.get(2)?,family_id:row.get(3)?,created_at:row.get(4)?,updated_at:row.get(5)?})}
pub(super) fn load_recipe(c:&rusqlite::Connection,id:i64)->Result<Option<Recipe>,MealPlannerError>{Ok(c.query_row("SELECT id,payload,owner_id,family_id,created_at,updated_at FROM recipes WHERE id=?1",[id],row_recipe).optional()?)}
fn timestamp()->i64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs() as i64}
#[cfg(test)]mod tests{use super::*;use crate::RecipeIngredient;fn store()->MealPlannerStore{MealPlannerStore::open_in_memory().unwrap()}fn draft(t:&str,i:&str,f:Option<&str>)->RecipeDraft{RecipeDraft{family_id:f.map(str::to_owned),title:t.into(),description:None,servings:2,ingredients:vec![RecipeIngredient{name:i.into(),amount:None,unit:None,preparation_note:None}],steps:vec!["Cook".into()],categories:vec![],tags:vec![],source:None,notes:None,dietary_information:vec![],allergens:None}}#[test]fn access_is_owner_or_matching_family(){let s=store();let a=s.create_recipe("a",draft("Private","x",None)).unwrap();let b=s.create_recipe("a",draft("Shared","y",Some("f1"))).unwrap();s.create_recipe("b",draft("Other","z",Some("f2"))).unwrap();assert_eq!(s.list_recipes("a",&[],None).unwrap().len(),2);assert!(s.get_recipe(a.id,"b",&[]).is_err());assert!(s.get_recipe(b.id,"b",&["f1".into()]).is_ok())}#[test]fn only_owner_can_mutate(){let s=store();let r=s.create_recipe("a",draft("Soup","x",Some("f1"))).unwrap();assert!(s.update_recipe(r.id,"b",draft("No","x",None)).is_err());assert_eq!(s.update_recipe(r.id,"a",draft("Soup","x",None)).unwrap().family_id,None);assert!(s.delete_recipe(r.id,"b").is_err());s.delete_recipe(r.id,"a").unwrap()}}